// Responsive image: serves the 480w/960w WebP variants generated by
// `npm run images`, falling back to the original file for non-JPG sources.
const variant = (src, w) => src.replace(/\.jpe?g$/i, `-${w}.webp`);

export default function Img({ src, alt, sizes = '100vw', priority = false, ...rest }) {
  const optimized = /\.jpe?g$/i.test(src);
  return (
    <img
      src={optimized ? variant(src, 960) : src}
      srcSet={optimized ? `${variant(src, 480)} 480w, ${variant(src, 960)} 960w` : undefined}
      sizes={optimized ? sizes : undefined}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      decoding="async"
      fetchPriority={priority ? 'high' : undefined}
      {...rest}
    />
  );
}
